const vert = `#version 300 es
  in vec4 aPosition;
  in vec2 aTexCoord;
  out vec2 vTexCoord;
  void main() {
    vTexCoord = aTexCoord;
    gl_Position = aPosition;
  }
`;

const frag = `#version 300 es
  precision mediump float;
  uniform sampler2D tex0;
  uniform vec2 texelSize;
  uniform vec2 canvasSize;
  uniform vec2 mouse;
  uniform float time;
  uniform vec2 iGrid;
  uniform sampler2D iAtlas;
  uniform vec2 iAtlasGrid;
  uniform float iLength;
  uniform float beatEnergy;
  uniform float bassEnergy;
  uniform float midEnergy;
  uniform float highEnergy;

  float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }
  vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
  vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }
  float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i  = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod289(i);
    vec4 p = permute(permute(permute(
               i.z + vec4(0.0, i1.z, i2.z, 1.0))
             + i.y + vec4(0.0, i1.y, i2.y, 1.0))
             + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    let n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j * ns.z);
    vec4 x = x_ *ns.x + ns.yyyy;
    vec4 y = y_ *ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
  }

  vec2 pixelate(vec2 uv, vec2 size) {
    return floor(uv * size) / size;
  }
  float mapVal(let val, let inMin, let inMax, let outMin, let outMax) {
    return outMin + (val - inMin) * (outMax - outMin) / (inMax - inMin);
  }
  vec3 palette(let t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
  }
  vec4 sprite(vec2 uv, sampler2D atlas, vec2 atlasGrid, let id) {
    uv /= atlasGrid;
    uv += vec2(mod(id, atlasGrid.x), floor(id / atlasGrid.x))/atlasGrid;
    return texture(atlas, uv);
  }

  in vec2 vTexCoord;
  out vec4 fragColor;
  void main() {
    let t = time*0.1*(1.0 + bassEnergy*0.5);
    vec2 uv = vTexCoord;
    uv -= 0.5;
    uv.x *= canvasSize.x/canvasSize.y;
    uv.y -= time*0.25;

    vec2 fuv = fract(uv*iGrid);
    vec2 puv = pixelate(uv, iGrid);

    let flow = .5+.5*snoise(vec3(puv, t));
    let id = floor(mapVal(flow, 0., 1., 0., iLength));
    vec4 col = sprite(fuv, iAtlas, iAtlasGrid, id);

    vec3 pal = palette( flow, vec3(.5), vec3(.5), vec3(1.), vec3(0.0, 0.8, 1.0) );
    col.rgb *= (pal + 0.3 + beatEnergy * 0.4);

    fragColor = col;
  }
`;


// let 3D let Canvas
const emojis = [" ", ".", ":", "-", "=", "+", "#", "%", "8", "*", "H", "M", "#", "X"];

let gfx, theShader;
let atlas = { atlas: null, cols: 0, rows: 0 };

const cols = 16;
const rows = 16;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(1);

  gfx = createGraphics(windowWidth, windowHeight, WEBGL);
  theShader = createShader(vert, frag);

  noStroke();
  gfx.noStroke();

  textFont("Consolas");
  atlas = getAtlas({
    array: emojis,
    cols: 5,
    unitSize: 256,
  });
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  let bE = (window.beatEnergy || 0.0);
  let bassE = (window.bassEnergy || 0.0);
  let midE = (window.midEnergy || 0.0);
  let highE = (window.highEnergy || 0.0);

  background(11, 16, 32);
  gfx.background(0);

  gfx.shader(theShader);
  theShader.setUniform("tex0", _renderer);
  theShader.setUniform("canvasSize", [width, height]);
  theShader.setUniform("texelSize", [1 / width, 1 / height]);
  theShader.setUniform("mouse", [mouseX / width, mouseY / height]);
  theShader.setUniform("time", frameCount / 60);
  theShader.setUniform("iGrid", [cols, rows]);
  theShader.setUniform("iAtlas", atlas.atlas);
  theShader.setUniform("iAtlasGrid", [atlas.cols, atlas.rows]);
  theShader.setUniform("iLength", emojis.length);
  theShader.setUniform("beatEnergy", bE);
  theShader.setUniform("bassEnergy", bassE);
  theShader.setUniform("midEnergy", midE);
  theShader.setUniform("highEnergy", highE);
  gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1);

  var t = frameCount * 0.01;
  rotateZ(sin(t * (1.0 + bE)) + cos(t));
  rotateY(map(sin(t), -1, 1, -0.35, 0.35) + bassE * 0.5);
  rotateX(map(cos(t), -1, 1, -0.35, 0.35));
  texture(gfx);

  const size = min(width, height) * 0.8;
  box(size, size, size * 2.5);
}

function getAtlas({ array, cols, unitSize, unitScale = 0.8 }) {
  var rows = ceil(array.length / cols);
  const gfxAtlas = createGraphics(unitSize * cols, unitSize * rows);
  gfxAtlas.fill(255);
  gfxAtlas.stroke(255);
  gfxAtlas.textAlign(CENTER, CENTER);
  gfxAtlas.textSize(unitSize * unitScale);
  array.forEach((value, index) => {
    gfxAtlas.text(
      value,
      unitSize / 2 + unitSize * (index % cols),
      unitSize / 2 + unitSize * floor(index / cols)
    );
  });
  return { atlas: gfxAtlas, cols: cols, rows: rows };
}

